<template>
  <div class="story-mode-page"><AuroraBackground/><AppNav/>
    <main class="story-shell">
      <section v-if="!started" class="story-hero glass">
        <div class="hero-copy"><div class="eyebrow">✨ ENGLISHXP STORY MODE</div><h1>Don’t study English.<br><span>Live it.</span></h1><p>Short interactive adventures where you read, choose, learn phrases and speak in real situations.</p><div class="hero-actions"><button class="primary" @click="startScenario(defaultScenario.id)">Start adventure <i class="ti ti-arrow-right"></i></button><router-link to="/stories" class="secondary">Read stories</router-link></div><div class="micro-stats"><span>⏱ 5–6 min</span><span>💬 Real conversations</span><span>⚡ XP & rewards</span></div></div>
        <div class="hero-scene"><div class="phone-card"><div class="phone-top"><span>London • 09:42</span><span>❤️ 5</span></div><div class="character-bubble"><span class="avatar">👩🏻‍💼</span><div><b>Maya</b><p>Welcome to London! Did you have a good flight?</p></div></div><div class="choice-preview">✓ Yes, it was great. Thanks!</div><div class="choice-preview muted">○ I have a flight yesterday.</div><div class="tiny-progress"><span></span></div></div></div>
      </section>

      <section v-if="!started" class="scenario-section"><div class="section-heading"><div><span class="eyebrow">CHOOSE YOUR ADVENTURE</span><h2>One story. Many English moments.</h2></div><span class="section-note">Short sessions • real situations</span></div><div class="scenario-grid"><button v-for="item in scenarios" :key="item.id" class="scenario-card glass" @click="startScenario(item.id)"><div class="scenario-icon" :class="item.color"><i :class="['ti',item.icon]"></i></div><div class="scenario-info"><span class="scenario-level">{{item.level}} • {{item.minutes}} min</span><h3>{{item.title}}</h3><p>{{item.description}}</p><div class="scenario-footer"><span>{{item.scenes.length}} scenes</span><span>Start <i class="ti ti-arrow-right"></i></span></div></div></button></div></section>

      <section v-if="started && !completed" class="adventure glass"><header class="adventure-header"><button class="icon-button" @click="exitAdventure"><i class="ti ti-x"></i></button><div class="adventure-title"><span>{{scenario.level}} • {{currentScene.location}}</span><strong>{{scenario.title}}</strong></div><div class="adventure-xp">+{{earnedXp}} XP</div></header><div class="adventure-progress"><span :style="{width:`${progress}%`}"></span></div><div class="scene-content"><div class="scene-heading"><span class="scene-mood">{{currentScene.mood}}</span><span>{{sceneIndex+1}} / {{scenario.scenes.length}}</span></div><div class="character-row"><div class="big-avatar">{{scenario.character.emoji}}</div><div><strong>{{currentScene.character}}</strong><small>{{scenario.character.role}}</small></div></div><div class="dialogue"><p>{{currentScene.line}}</p><button class="translation" @click="showTranslation=!showTranslation">🌐 {{showTranslation?currentScene.translation:'Show translation'}}</button></div><div v-if="currentScene.word" class="word-chip" @click="showWord=!showWord">✨ <span>Learn: <b>{{currentScene.word.en}}</b></span><span class="word-arrow">{{showWord?'−':'+'}}</span></div><div v-if="showWord && currentScene.word" class="word-detail"><b>{{currentScene.word.en}}</b><span>{{currentScene.word.uz}}</span><em>{{currentScene.word.example}}</em></div>
        <div v-if="!currentScene.speaking" class="choices"><button v-for="choice in currentScene.choices" :key="choice.text" class="choice" :class="choiceState(choice)" :disabled="answered" @click="choose(choice)"><span class="choice-mark">{{choiceState(choice)==='correct'?'✓':choiceState(choice)==='wrong'?'×':'○'}}</span>{{choice.text}}</button></div>
        <div v-else class="speaking-card"><div class="speaking-icon">🎤</div><h3>Your turn to speak</h3><p>Say one or two sentences for about 20 seconds.</p><button class="primary speak-button" :class="{listening}" @click="startSpeaking">{{listening?'Listening…':'Start speaking'}}</button><p v-if="speechText" class="speech-result">“{{speechText}}”</p></div>
        <div v-if="feedback" class="feedback" :class="feedback.type"><div class="feedback-icon">{{feedback.type==='correct'?'✓':'!'}}</div><div><strong>{{feedback.title}}</strong><p>{{feedback.message}}</p><span v-if="feedback.phrase">Useful phrase: <b>{{feedback.phrase}}</b></span></div></div><button v-if="feedback" class="continue primary" @click="nextScene">{{sceneIndex===scenario.scenes.length-1?'Finish adventure':'Continue'}} <i class="ti ti-arrow-right"></i></button>
      </div></section>

      <section v-if="completed" class="complete-card glass"><div class="confetti">🎉</div><span class="eyebrow">ADVENTURE COMPLETE</span><h1>You used English in the real world.</h1><p>{{scenario.title}} finished. You made {{correctAnswers}} strong choices and learned {{scenario.scenes.length}} useful phrases.</p><div class="result-grid"><div><strong>+{{earnedXp}}</strong><span>XP earned</span></div><div><strong>{{correctAnswers}}/{{scenario.scenes.length}}</strong><span>good choices</span></div><div><strong>{{scenario.scenes.length}}</strong><span>new phrases</span></div></div><div class="complete-actions"><button class="primary" @click="restart">Play again</button><router-link to="/dashboard" class="secondary">Back to dashboard</router-link><router-link to="/roleplay" class="secondary">Try AI Roleplay</router-link></div></section>
    </main>
  </div>
</template>

<script setup>
import {computed,ref,onMounted} from 'vue'
import AppNav from '../components/AppNav.vue'
import AuroraBackground from '../components/AuroraBackground.vue'
import {STORY_MODE_SCENARIOS,getStoryModeScenario} from '../data/storyMode.js'
import {useUserStore} from '../stores/userStore.js'
import {useContentStore} from '../stores/contentStore.js'
import {useSpeechRecognition} from '../composables/useSpeechRecognition.js'
const userStore=useUserStore()
const contentStore=useContentStore()
const customScenarios=ref([])
const scenarios=computed(()=>[...STORY_MODE_SCENARIOS,...customScenarios.value])
const defaultScenario=STORY_MODE_SCENARIOS[0]
const started=ref(false),completed=ref(false),scenario=ref(defaultScenario),sceneIndex=ref(0),answered=ref(false),selectedChoice=ref(null),feedback=ref(null),showTranslation=ref(false),showWord=ref(false),earnedXp=ref(0),correctAnswers=ref(0),speechText=ref('')
const {isListening:listening,transcript,startListening,stopListening}=useSpeechRecognition()
const currentScene=computed(()=>scenario.value.scenes[sceneIndex.value]),progress=computed(()=>Math.round(((sceneIndex.value+(feedback.value?1:0))/scenario.value.scenes.length)*100))
function toCustomScenario(entry){
  const s=entry.story||{}
  const questions=s.questions||[]
  const sentences=s.sentences||[]
  const scenes=(questions.length?questions:sentences.map((x,i)=>({question:x.en,options:[],correct:''}))).map((q,i)=>{
    const sentence=sentences[i]||sentences[0]||{}
    const opts=(q.options||[]).map((text,idx)=>({text,correct:text===q.correct,reply:text===q.correct?'Correct! Nice choice.':'Good try — check the example again.',phrase:text}))
    return {id:`${entry.id}-${i}`,location:'Story lesson',mood:'Choose',character:'EnglishXP',line:q.question||sentence.en||'Read the sentence and choose the best answer.',translation:sentence.uz||'',choices:opts.length?opts:[{text:sentence.en||'Continue',correct:true,reply:'Great reading.',phrase:sentence.en||''}],word:sentence.en?{en:sentence.en,uz:sentence.uz||'',example:sentence.en}:null}
  })
  return {id:`custom-${entry.id}`,title:s.titleEn||s.title||'Custom Story',uzTitle:s.title||'',level:s.cefr||`A${s.level||1}`,minutes:s.minutes||3,icon:'ti-book-2',color:'blue',description:'Admin Studio tomonidan qo‘shilgan interaktiv story.',character:{name:'EnglishXP',role:'story guide',emoji:'📘'},scenes}
}
async function loadCustomStories(){
  await contentStore.fetchCustomContent()
  customScenarios.value=contentStore.customStoryDocs.map(toCustomScenario)
}
function startScenario(id){const selected=scenarios.value.find(x=>x.id===id)||getStoryModeScenario(id);scenario.value=selected;started.value=true;completed.value=false;sceneIndex.value=0;correctAnswers.value=0;earnedXp.value=0;resetScene()}
function resetScene(){answered.value=false;selectedChoice.value=null;feedback.value=null;showTranslation.value=false;showWord.value=false;speechText.value=''}
function choose(choice){if(answered.value)return;answered.value=true;selectedChoice.value=choice;if(choice.correct){correctAnswers.value++;earnedXp.value+=12;feedback.value={type:'correct',title:'Nice choice!',message:choice.reply,phrase:choice.phrase}}else{earnedXp.value+=4;feedback.value={type:'wrong',title:'Good try!',message:choice.reply,phrase:choice.phrase}}}
function choiceState(choice){if(!answered.value)return '';if(choice===selectedChoice.value&&choice.correct)return 'correct';if(choice===selectedChoice.value&&!choice.correct)return 'wrong';return ''}
async function startSpeaking(){speechText.value='';await startListening();speechText.value=transcript.value||'';if(speechText.value){answered.value=true;correctAnswers.value++;earnedXp.value+=15;feedback.value={type:'correct',title:'You spoke!',message:'Great job. The goal is using English without stopping.',phrase:currentScene.value.choices[0]?.phrase}}}
async function nextScene(){if(sceneIndex.value>=scenario.value.scenes.length-1){completed.value=true;const finalXp=Math.max(20,earnedXp.value);earnedXp.value=finalXp;await userStore.addXp(finalXp,'reading');await userStore.recordSkillScore('reading',correctAnswers.value,scenario.value.scenes.length);return}sceneIndex.value++;resetScene()}
function restart(){startScenario(scenario.value.id)}
function exitAdventure(){started.value=false;completed.value=false;correctAnswers.value=0;earnedXp.value=0}
onMounted(loadCustomStories)
</script>

<style scoped>
