low:hidden}.tiny-progress span{display:block;width:45%;height:100%;background:var(--accent)}.scenario-section{padding-top:58px}.section-heading{display:flex;justify-content:space-between;align-items:end;margin-bottom:22px}.section-heading h2{font-size:30px;margin:7px 0}.section-note{font-size:12px;color:var(--text-muted)}.scenario-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.scenario-card{text-align:left;border:1px solid var(--border);padding:22px;border-radius:22px;display:flex;gap:18px;cursor:pointer;transition:.2s}.scenario-card:hover{transform:translateY(-3px);border-color:var(--accent)}.scenario-icon{width:58px;height:58px;border-radius:17px;display:grid;place-items:center;font-size:25px;flex:none;background:var(--accent-soft);color:var(--accent)}.scenario-icon.purple{background:rgba(124,92,255,.12);color:#7657e8}.scenario-level{font-size:11px;color:var(--accent-dim);font-weight:800}.scenario-info h3{margin:6px 0;font-size:18px}.scenario-info p{font-size:13px;color:var(--text-secondary);line-height:1.5;margin:0 0 17px}.scenario-footer{display:flex;justify-content:space-between;font-size:12px;color:var(--text-muted)}.scenario-footer span:last-child{color:var(--accent);font-weight:800}.adventure{max-width:820px;margin:15px auto 0;border-radius:28px;overflow:hidden}.adventure-header{display:flex;align-items:center;gap:14px;padding:16px 18px;border-bottom:1px solid var(--border)}.icon-button{border:0;background:transparent;font-size:20px;color:var(--text-secondary);cursor:pointer}.adventure-title{flex:1;display:flex;flex-direction:column;gap:3px}.adventure-title span{font-size:11px;color:var(--text-muted)}.adventure-title strong{font-size:14px}.adventure-xp{font-size:12px;font-weight:800;color:var(--accent)}.adventure-progress{height:5px;background:var(--border)}.adventure-progress span{display:block;height:100%;background:var(--accent);transition:.3s}.scene-content{padding:36px}.scene-heading{display:flex;justify-content:space-between;color:var(--text-muted);font-size:12px}.scene-mood{color:var(--accent);font-weight:800;text-transform:uppercase;letter-spacing:.8px}.character-row{display:flex;gap:12px;align-items:center;margin:30px 0 15px}.big-avatar{width:58px;height:58px;font-size:31px}.character-row strong,.character-row small{display:block}.character-row small{color:var(--text-muted);font-size:11px;margin-top:3px}.dialogue{background:var(--accent-soft);border-radius:22px;padding:24px}.dialogue p{font-size:22px;line-height:1.45;margin:0 0 16px;font-weight:700}.translation{border:0;background:transparent;color:var(--accent-dim);font-size:12px;cursor:pointer;padding:0}.word-chip{margin-top:15px;display:flex;align-items:center;gap:8px;background:var(--surface);border:1px solid var(--border);padding:12px 14px;border-radius:14px;cursor:pointer;font-size:12px}.word-arrow{margin-left:auto;font-size:18px}.word-detail{padding:12px 14px;background:rgba(255,255,255,.55);border:1px dashed var(--border);border-top:0;border-radius:0 0 14px 14px;display:flex;flex-direction:column;gap:4px}.word-detail span{color:var(--text-secondary);font-size:12px}.word-detail em{color:var(--text-muted);font-size:11px}.choices{display:grid;gap:10px;margin-top:20px}.choice{width:100%;text-align:left;padding:16px;border-radius:15px;border:1px solid var(--border);background:var(--surface);cursor:pointer;font-weight:700;color:var(--text-primary);display:flex;gap:12px;align-items:center}.choice:hover:not(:disabled){border-color:var(--accent)}.choice.correct{border-color:var(--accent);background:var(--accent-soft)}.choice.wrong{border-color:#ef6a6a;background:rgba(239,106,106,.08)}.choice-mark{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;background:rgba(0,0,0,.05);flex:none}.speaking-card{text-align:center;padding:30px 15px}.speaking-icon{font-size:38px}.speaking-card h3{margin:8px 0 5px}.speaking-card p{color:var(--text-secondary);font-size:13px}.speak-button.listening{animation:pulse 1s infinite}.speech-result{background:var(--accent-soft);padding:13px;border-radius:13px;font-style:italic}.feedback{margin-top:18px;border-radius:16px;padding:15px;display:flex;gap:12px;align-items:flex-start}.feedback.correct{background:var(--accent-soft)}.feedback.wrong{background:rgba(239,106,106,.08)}.feedback-icon{font-weight:900}.feedback strong,.feedback p,.feedback span{display:block}.feedback p{font-size:12px;color:var(--text-secondary);margin:4px 0}.feedback span{font-size:11px;color:var(--text-muted)}.continue{margin-top:14px;width:100%}.complete-card{text-align:center;max-width:760px;margin:70px auto 0;padding:55px 35px;border-radius:30px}.confetti{font-size:58px}.complete-card h1{font-size:38px;margin:12px 0}.complete-card>p{color:var(--text-secondary);line-height:1.6}.result-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:30px 0}.result-grid div{padding:18px;background:var(--accent-soft);border-radius:17px}.result-grid strong,.result-grid span{display:block}.result-grid strong{font-size:23px;color:var(--accent)}.result-grid span{font-size:11px;color:var(--text-muted);margin-top:4px}.complete-actions{justify-content:center}@keyframes pulse{50%{transform:scale(1.03);box-shadow:0 0 0 10px rgba(0,0,0,.04)}}@media(max-width:800px){.story-hero{grid-template-columns:1fr;padding:32px;min-height:auto}.hero-copy h1{font-size:43px}.scenario-grid{grid-template-columns:1fr}.section-heading{display:block}.section-note{display:block;margin-top:10px}.scene-content{padding:24px}.dialogue p{font-size:18px}.result-grid{grid-template-columns:1fr 1fr}.complete-card h1{font-size:30px}}@media(max-width:520px){.story-shell{padding:20px 14px 70px}.story-hero{padding:24px;border-radius:24px}.hero-scene{display:none}.scenario-card{padding:17px}.result-grid{grid-template-columns:1fr}.complete-card{padding:40px 20px}}
